  [f"1,5 kg|de cuisses de poulet|{CUISSE}|3", "2|épis de maïs en tronçons (ou 300 g de maïs)|Maïs doux|2", "2|bananes plantain vertes|Plantain (banane à cuire)|2", "500 g|de manioc (surgelé)|Manioc / yuca|2", f"500 g|de pommes de terre|{PDT}|2", f"1|oignon|{OIG}|1", f"3 gousses|d'ail|{AIL}|1", f"1 c. à c.|de cumin|{CUMIN}|1", f"1 bouquet|de coriandre|{CORI}|2", f"2|citrons verts|{CITV}|1", "2|avocats|Avocat|1", f"2 c. à c.|de sel|{SEL}|1"],
