  [f"600 g|de pommes de terre|{PDT}|3", f"2|poivrons verts|{POIVRON}|2", f"1|oignon|{OIG}|2", "12|tortillas de maïs|Tortillas de maïs|3", "100 g|de feta ou de queso fresco|Feta|2", f"10 cl|de crème|{CF}|1", f"1 bouquet|de coriandre|{CORI}|1", f"2|citrons verts|{CITV}|2", f"1|piment vert|{PIMENT}|1", f"2 c. à s.|d'huile|{HN}|1", f"1 pincée|de sel|{SEL}|1"],
